"任何房间：出征视野 +{0}，初始积分倍率 +{1}。契合「运势 / 特殊」：出征地图一开始就全亮，积分倍率再 +{2}。": "Любая комната: обзор в походе +{0}, стартовый множитель очков +{1}. В комнате «Судьба / Особое»: карта похода сразу полностью открыта, множитель ещё +{2}.",
