"任何房间：出征部队生命 +{0}%。契合「医疗」：医院回复 +{1}%，领袖每天再回 {2}%。": "Любая комната: здоровье отрядов в походе +{0}%. В комнате «Медицина»: лечение в больнице +{1}%, лидер лечит ещё {2}% в день.",
"任何房间：图纸掉率 +{0}%。契合「科幻」：基地每天 +{1} 灵魂碎片。": "Любая комната: шанс чертежей +{0}%. В комнате «Фантастика»: база получает осколки душ +{1} в день.",
