"任何房间：基地每天 +{0} 灵魂碎片。契合「魔法」：基地每天再 +{1} 灵魂碎片。": "Любая комната: база получает осколки душ +{0} в день. В комнате «Магия»: ещё +{1} в день.",
"任何房间：基地每天 +{0} 物资。契合「后勤」：这个房间自己的效果 ×{1}。": "Любая комната: база получает припасы +{0} в день. В комнате «Снабжение»: собственный эффект этой комнаты ×{1}.",
