"任何房间：建造时间减半，建成返还 {0}% 物资。契合「奇观」：返还提高到 {1}%。": "Любая комната: строительство вдвое быстрее, по завершении возвращается {0}% припасов. В комнате «Чудо»: возврат до {1}%.",
"任何房间：所有防御塔伤害 +{0}%。契合「武器」：射程 +{1}，攻速 +{2}%。": "Любая комната: урон всех оборонительных башен +{0}%. В комнате «Оружие»: дальность +{1}, скорость атаки +{2}%.",
"任何房间：挖掘费用 -{0}%。契合「特殊」：所有建造少花 {1} 天。": "Любая комната: стоимость раскопок -{0}%. В комнате «Особое»: любое строительство на {1} дн. короче.",
"任何房间：每场战斗初始积分倍率 +{0}。契合「锻造」：打造的宝物品质必定 +{1}。": "Любая комната: стартовый множитель очков в каждом бою +{0}. В комнате «Ковка»: качество выкованных реликвий всегда +{1}.",
"任何房间：领袖技能冷却少 {0} 个节点。契合「运势」：出征开局多带 {1} 个支援道具（至少转出「史诗」效果）。": "Любая комната: перезарядка навыка лидера −{0} эт. В комнате «Судьба»: в начале похода больше предметов поддержки: +{1} (эффект не ниже «Эпического»).",
"任何房间：领袖攻击 +{0}%。契合「武器」：伤害 +{1}%，每次攻击放出连锁闪电（跳 {2} 个敌人）。": "Любая комната: атака лидера +{0}%. В комнате «Оружие»: урон +{1}%, каждая атака выпускает цепную молнию (прыжков: {2}).",
"任何房间：领袖每天回复 {0}% 生命（不需要医院）。契合「医疗 / 水域」：医院回复 +{1}%；水域武器射程 +{2}。": "Любая комната: лидер восстанавливает {0}% здоровья в день (больница не нужна). В комнате «Медицина / Вода»: лечение в больнице +{1}%; дальность водного оружия +{2}.",
